class Solution {

    /**
     * @param Integer[] $salary
     * @return Float
     */
    function average($salary) {
        $sum = 0;
        $min = $salary[0];
        $max = $salary[0];

        foreach ($salary as $value) {
            $sum += $value;
            $min = min($min, $value);
            $max = max($max, $value);
        }

        return ($sum - $min - $max) / (count($salary) - 2);
    }
}
