<?php
class Solution {

    /**
     * @param Integer $left
     * @param Integer $right
     * @return String
     */
    function abbreviateProduct($left, $right) {
        $modulus = 10000000000;
        $mod = 1;
        $count2 = 0;
        $count5 = 0;
        $logValue = 0.0;

        for ($i = $left; $i <= $right; $i++) {
            $n = $i;
            $logValue += log10($i);

            while ($n % 2 === 0) {
                $count2++;
                $n = intdiv($n, 2);
            }

            while ($n % 5 === 0) {
                $count5++;
                $n = intdiv($n, 5);
            }

            $mod = ($mod * $n) % $modulus;
        }

        $trailingZeros = min($count2, $count5);
        $extra2 = $count2 - $trailingZeros;
        $extra5 = $count5 - $trailingZeros;

        for ($i = 0; $i < $extra2; $i++) {
            $mod = ($mod * 2) % $modulus;
        }

        for ($i = 0; $i < $extra5; $i++) {
            $mod = ($mod * 5) % $modulus;
        }

        $logValue -= $trailingZeros;
        $digits = (int)floor($logValue) + 1;

        if ($digits <= 10) {
            return (string)$mod . "e" . $trailingZeros;
        }

        $fraction = $logValue - floor($logValue);
        $leading = (int)floor(pow(10, $fraction + 4));

        if ($leading >= 100000) {
            $leading = 99999;
        }

        $suffix = $mod % 100000;
        $suffixString = str_pad((string)$suffix, 5, "0", STR_PAD_LEFT);

        return (string)$leading . "..." . $suffixString . "e" . $trailingZeros;
    }
}
