     */
    function areOccurrencesEqual($s) {
        $counts = array_fill(0, 26, 0);

        for ($i = 0; $i < strlen($s); $i++) {
            $index = ord($s[$i]) - ord('a');
            $counts[$index]++;
        }

        $frequency = 0;

        foreach ($counts as $count) {
            if ($count > 0) {
                if ($frequency === 0) {
                    $frequency = $count;
                } elseif ($count !== $frequency) {
                    return false;
                }
            }
        }

        return true;
    }
}
