    /**
     * @param Integer[][] $coordinates
     * @return Boolean
     */
    function checkStraightLine($coordinates) {
        $x0 = $coordinates[0][0];
        $y0 = $coordinates[0][1];
        $x1 = $coordinates[1][0];
        $y1 = $coordinates[1][1];

        $dx = $x1 - $x0;
