     */
    function clumsy($n) {
        $stack = [$n];
        $step = 0;

        for ($i = $n - 1; $i >= 1; $i--) {
            $index = count($stack) - 1;

            switch ($step % 4) {
                case 0:
                    $stack[$index] *= $i;
                    break;
                case 1:
