<?php

class MKAverage {
    private $m;
    private $k;
    private $maxValue = 100000;

    private $queue;
    private $head = 0;
    private $count = 0;
    private $totalSum = 0;

    private $countBit;
    private $sumBit;

    /**
     * @param Integer $m
     * @param Integer $k
     */
    function __construct($m, $k) {
        $this->m = $m;
        $this->k = $k;

        $this->queue = array_fill(0, $m, 0);
        $this->countBit = array_fill(0, $this->maxValue + 2, 0);
        $this->sumBit = array_fill(0, $this->maxValue + 2, 0);
    }

    /**
     * @param Integer $num
     * @return NULL
     */
    function addElement($num) {
        if ($this->count == $this->m) {
            $old = $this->queue[$this->head];
            $this->updateBits($old, -1);
            $this->totalSum -= $old;

            $this->head = ($this->head + 1) % $this->m;
            $this->count--;
        }

        $index = ($this->head + $this->count) % $this->m;
        $this->queue[$index] = $num;
        $this->count++;

        $this->updateBits($num, 1);
        $this->totalSum += $num;
    }

    /**
     * @return Integer
     */
    function calculateMKAverage() {
        if ($this->count < $this->m) {
            return -1;
        }

        $smallestK = $this->sumOfSmallest($this->k);
        $smallestRemaining = $this->sumOfSmallest($this->m - $this->k);

        $middleSum = $smallestRemaining - $smallestK;
        return intdiv($middleSum, $this->m - 2 * $this->k);
    }

    private function updateBits($value, $delta) {
        for ($i = $value; $i <= $this->maxValue; $i += $i & (-$i)) {
            $this->countBit[$i] += $delta;
            $this->sumBit[$i] += $delta * $value;
        }
    }

    private function prefixCount($index) {
        $result = 0;

        for ($i = $index; $i > 0; $i -= $i & (-$i)) {
            $result += $this->countBit[$i];
        }

        return $result;
    }

    private function prefixSum($index) {
        $result = 0;

        for ($i = $index; $i > 0; $i -= $i & (-$i)) {
            $result += $this->sumBit[$i];
        }

        return $result;
    }

    private function findKth($k) {
        $index = 0;
        $step = 1;

        while (($step << 1) <= $this->maxValue) {
            $step <<= 1;
        }

        for (; $step > 0; $step >>= 1) {
            $next = $index + $step;

            if ($next <= $this->maxValue && $this->countBit[$next] < $k) {
                $index = $next;
                $k -= $this->countBit[$next];
            }
        }

        return $index + 1;
    }

    private function sumOfSmallest($amount) {
        if ($amount <= 0) {
            return 0;
        }

        $value = $this->findKth($amount);
        $beforeCount = $this->prefixCount($value - 1);
        $beforeSum = $this->prefixSum($value - 1);

        return $beforeSum + ($amount - $beforeCount) * $value;
    }
}
