class Solution {

    /**
     * @param String[] $queries
     * @param String[] $words
     * @return Integer[]
     */
    function numSmallerByFrequency($queries, $words) {
        $frequency = function ($s) {
            $minChar = $s[0];
            $count = 0;
            $length = strlen($s);

            for ($i = 0; $i < $length; $i++) {
                if ($s[$i] < $minChar) {
                    $minChar = $s[$i];
                    $count = 1;
                } elseif ($s[$i] === $minChar) {
                    $count++;
                }
            }

            return $count;
        };

        $wordFrequencies = [];
        foreach ($words as $word) {
            $wordFrequencies[] = $frequency($word);
        }

        $answer = [];
        foreach ($queries as $query) {
            $queryFrequency = $frequency($query);
            $count = 0;

            foreach ($wordFrequencies as $wordFrequency) {
                if ($wordFrequency > $queryFrequency) {
                    $count++;
                }
            }

            $answer[] = $count;
        }

        return $answer;
    }
}
