    function maxScore($nums) {
        $m = count($nums);
        $totalMasks = 1 << $m;

        $bits = array_fill(0, $totalMasks, 0);
        for ($mask = 1; $mask < $totalMasks; $mask++) {
            $bits[$mask] = $bits[$mask >> 1] + ($mask & 1);
        }

        $dp = array_fill(0, $totalMasks, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask < $totalMasks; $mask++) {
            if ($dp[$mask] < 0 || $bits[$mask] === $m) {
                continue;
            }

            $first = -1;
            for ($i = 0; $i < $m; $i++) {
                if (($mask & (1 << $i)) === 0) {
                    $first = $i;
                    break;
                }
            }

            $operation = intdiv($bits[$mask], 2) + 1;

            for ($j = $first + 1; $j < $m; $j++) {
                if (($mask & (1 << $j)) !== 0) {
                    continue;
