                $nextMask = $mask | (1 << $first) | (1 << $j);
                $gain = $operation * $this->gcd($nums[$first], $nums[$j]);
                $dp[$nextMask] = max($dp[$nextMask], $dp[$mask] + $gain);
            }
        }

