                $offset = (($state & 1) === 0) ? 0 : 1;
                $nextMask = $mask | (1 << ($shift + $offset));
                $nextValue = $current + ($nums[$k] & ($slot + 1));

                if (!isset($dp[$nextMask]) || $nextValue > $dp[$nextMask]) {
                    $dp[$nextMask] = $nextValue;
                }
            }
        }

