    function maxStudents($seats) {
        $m = count($seats);
        $n = count($seats[0]);

        $dp = [0 => 0];

        for ($i = 0; $i < $m; $i++) {
            $available = 0;

            for ($j = 0; $j < $n; $j++) {
                if ($seats[$i][$j] === '.') {
                    $available |= (1 << $j);
