                if (($mask | $available) !== $available) {
                    continue;
                }

                if (($mask & ($mask << 1)) !== 0) {
                    continue;
                }

                $students = 0;
                $temp = $mask;
                while ($temp > 0) {
                    $students += $temp & 1;
                    $temp >>= 1;
