class Solution {

    /**
     * @param Integer[] $flowers
     * @param Integer $newFlowers
     * @param Integer $target
     * @param Integer $full
     * @param Integer $partial
     * @return Integer
     */
    function maximumBeauty($flowers, $newFlowers, $target, $full, $partial) {
        $n = count($flowers);
        sort($flowers, SORT_NUMERIC);

        for ($i = 0; $i < $n; $i++) {
            if ($flowers[$i] > $target) {
                $flowers[$i] = $target;
            }
        }

        $prefix = array_fill(0, $n + 1, 0);
        for ($i = 0; $i < $n; $i++) {
            $prefix[$i + 1] = $prefix[$i] + $flowers[$i];
        }

        $completeInitially = 0;
        while (
            $completeInitially < $n &&
            $flowers[$n - 1 - $completeInitially] >= $target
        ) {
            $completeInitially++;
        }

        $less = array_fill(0, $target, 0);
        $pointer = 0;
        for ($level = 0; $level < $target; $level++) {
            while ($pointer < $n && $flowers[$pointer] < $level) {
                $pointer++;
            }
            $less[$level] = $pointer;
        }

        $answer = 0;

        for ($complete = $completeInitially; $complete <= $n; $complete++) {
            $incomplete = $n - $complete;

            $completeCost =
                $complete * $target -
                ($prefix[$n] - $prefix[$incomplete]);

            if ($completeCost > $newFlowers) {
                break;
            }

            $beauty = $complete * $full;

            if ($incomplete > 0) {
                $remaining = $newFlowers - $completeCost;
                $low = 0;
                $high = $target - 1;

                while ($low < $high) {
                    $mid = intdiv($low + $high + 1, 2);

                    $count = $less[$mid];
                    if ($count > $incomplete) {
                        $count = $incomplete;
                    }

                    $needed = $mid * $count - $prefix[$count];

                    if ($needed <= $remaining) {
                        $low = $mid;
                    } else {
                        $high = $mid - 1;
                    }
                }

                $beauty += $low * $partial;
            }

            if ($beauty > $answer) {
                $answer = $beauty;
            }
        }

        return $answer;
    }
}
