class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function numOfWays($nums) {
        $mod = 1000000007;
        $n = count($nums);

        $fact = array_fill(0, $n + 1, 1);
        for ($i = 1; $i <= $n; $i++) {
            $fact[$i] = ($fact[$i - 1] * $i) % $mod;
        }

        $powerMod = function ($base, $exp) use ($mod) {
            $result = 1;
            $base %= $mod;

            while ($exp > 0) {
                if ($exp % 2 === 1) {
                    $result = ($result * $base) % $mod;
                }
                $base = ($base * $base) % $mod;
                $exp = intdiv($exp, 2);
            }

            return $result;
        };

        $invFact = array_fill(0, $n + 1, 1);
        $invFact[$n] = $powerMod($fact[$n], $mod - 2);

        for ($i = $n - 1; $i >= 0; $i--) {
            $invFact[$i] = ($invFact[$i + 1] * ($i + 1)) % $mod;
        }

        $dfs = function ($arr) use (&$dfs, $fact, $invFact, $mod) {
            $size = count($arr);

            if ($size <= 2) {
                return 1;
            }

            $root = $arr[0];
            $left = [];
            $right = [];

            for ($i = 1; $i < $size; $i++) {
                if ($arr[$i] < $root) {
                    $left[] = $arr[$i];
                } else {
                    $right[] = $arr[$i];
                }
            }

            $leftSize = count($left);
            $rightSize = count($right);

            $leftWays = $dfs($left);
            $rightWays = $dfs($right);

            $choose = $fact[$leftSize + $rightSize];
            $choose = ($choose * $invFact[$leftSize]) % $mod;
            $choose = ($choose * $invFact[$rightSize]) % $mod;

            $result = ($choose * $leftWays) % $mod;
            $result = ($result * $rightWays) % $mod;

            return $result;
        };

        $answer = $dfs($nums);
        return ($answer - 1 + $mod) % $mod;
    }
}
