    /**
     * @param String $date1
     * @param String $date2
     * @return Integer
     */
    function daysBetweenDates($date1, $date2) {
        $toDays = function ($date) {
            $year = (int)substr($date, 0, 4);
            $month = (int)substr($date, 5, 2);
            $day = (int)substr($date, 8, 2);

            $isLeap = function ($y) {
                return ($y % 400 === 0) || ($y % 4 === 0 && $y % 100 !== 0);
            };

            $days = 365 * ($year - 1)
                + intdiv($year - 1, 4)
                - intdiv($year - 1, 100)
                + intdiv($year - 1, 400);

            $monthDays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

            for ($m = 1; $m < $month; $m++) {
                $days += $monthDays[$m - 1];
                if ($m === 2 && $isLeap($year)) {
                    $days++;
                }
            }

            return $days + $day;
        };

        return abs($toDays($date1) - $toDays($date2));
    }
}
