class Solution {

    /**
     * @param Integer $n
     * @param Integer[][] $restrictions
     * @param Integer[][] $requests
     * @return Boolean[]
     */
    function friendRequests($n, $restrictions, $requests) {
        $parent = [];
        $size = [];

        for ($i = 0; $i < $n; $i++) {
            $parent[$i] = $i;
            $size[$i] = 1;
        }

        $find = function ($x) use (&$find, &$parent) {
            if ($parent[$x] !== $x) {
                $parent[$x] = $find($parent[$x]);
            }
            return $parent[$x];
        };

        $result = [];

        foreach ($requests as $request) {
            $u = $request[0];
            $v = $request[1];

            $rootU = $find($u);
            $rootV = $find($v);

            if ($rootU === $rootV) {
                $result[] = true;
                continue;
            }

            $allowed = true;

            foreach ($restrictions as $restriction) {
                $rx = $find($restriction[0]);
                $ry = $find($restriction[1]);

                if (($rx === $rootU && $ry === $rootV) ||
                    ($rx === $rootV && $ry === $rootU)) {
                    $allowed = false;
                    break;
                }
            }

            $result[] = $allowed;

            if ($allowed) {
                if ($size[$rootU] < $size[$rootV]) {
                    $temp = $rootU;
                    $rootU = $rootV;
                    $rootV = $temp;
                }

                $parent[$rootV] = $rootU;
                $size[$rootU] += $size[$rootV];
            }
        }

        return $result;
    }
}
