class Solution {
    function minSessions($tasks, $sessionTime) {
        $n = count($tasks);
        $limit = 1 << $n;

        $bitIndex = [];
        for ($i = 0; $i < $n; $i++) {
            $bitIndex[1 << $i] = $i;
        }

        $sum = array_fill(0, $limit, 0);
        for ($mask = 1; $mask < $limit; $mask++) {
            $bit = $mask & (-$mask);
            $sum[$mask] = $sum[$mask ^ $bit] + $tasks[$bitIndex[$bit]];
        }

        $dp = array_fill(0, $limit, PHP_INT_MAX);
        $dp[0] = 0;

        for ($mask = 1; $mask < $limit; $mask++) {
            $sub = $mask;

            while ($sub > 0) {
                if ($sum[$sub] <= $sessionTime) {
                    $remaining = $mask ^ $sub;
                    $dp[$mask] = min($dp[$mask], $dp[$remaining] + 1);
                }

                $sub = ($sub - 1) & $mask;
            }
        }

        return $dp[$limit - 1];
    }
