    /**
     * @param String $s1
     * @param String $s2
     * @return Boolean
     */
    function isScramble($s1, $s2) {
        $n = strlen($s1);

        if ($n !== strlen($s2)) {
            return false;
        }

        $prefix1 = array_fill(0, $n + 1, []);
        $prefix2 = array_fill(0, $n + 1, []);

        $prefix1[0] = array_fill(0, 26, 0);
        $prefix2[0] = array_fill(0, 26, 0);

        for ($i = 0; $i < $n; $i++) {
            $prefix1[$i + 1] = $prefix1[$i];
            $prefix2[$i + 1] = $prefix2[$i];

            $c1 = ord($s1[$i]) - 97;
            $c2 = ord($s2[$i]) - 97;

            $prefix1[$i + 1][$c1]++;
            $prefix2[$i + 1][$c2]++;
        }

        $memo = [];

        $dfs = function ($i, $j, $len) use (&$dfs, &$memo, &$prefix1, &$prefix2, $s1, $s2) {
            $key = $i . ',' . $j . ',' . $len;

            if (isset($memo[$key])) {
                return $memo[$key];
            }

            for ($c = 0; $c < 26; $c++) {
                $count1 = $prefix1[$i + $len][$c] - $prefix1[$i][$c];
                $count2 = $prefix2[$j + $len][$c] - $prefix2[$j][$c];

                if ($count1 !== $count2) {
                    $memo[$key] = false;
                    return false;
                }
            }

            if ($len === 1) {
                $result = ($s1[$i] === $s2[$j]);
                $memo[$key] = $result;
                return $result;
            }

            for ($split = 1; $split < $len; $split++) {
                if (
                    $dfs($i, $j, $split) &&
                    $dfs($i + $split, $j + $split, $len - $split)
                ) {
                    $memo[$key] = true;
                    return true;
                }

                if (
                    $dfs($i, $j + $len - $split, $split) &&
                    $dfs($i + $split, $j, $len - $split)
                ) {
                    $memo[$key] = true;
                    return true;
                }
            }

            $memo[$key] = false;
            return false;
        };

        return $dfs(0, 0, $n);
    }
}
