    function numTriplets($nums1, $nums2) {
        $buildFrequency = function ($nums) {
            $freq = [];
            foreach ($nums as $value) {
                if (isset($freq[$value])) {
                    $freq[$value]++;
                } else {
                    $freq[$value] = 1;
                }
            }
