                    }

                    if ($first === $second) {
                        $pairs = intdiv($firstCount * ($firstCount - 1), 2);
                    } else {
                        $pairs = $firstCount * $otherFreq[$second];
                    }

                    $result += $sourceCount * $pairs;
                }
            }

            return $result;
        };

        $freq1 = $buildFrequency($nums1);
        $freq2 = $buildFrequency($nums2);

        return $countTriplets($freq1, $freq2) + $countTriplets($freq2, $freq1);
