            }
            return $idA < $idB;
        };

        $push = function (&$values, &$ids, $value, $id, $isMin) use ($better) {
            $pos = count($values);
            $values[] = $value;
            $ids[] = $id;

            while ($pos > 0) {
                $parent = intdiv($pos - 1, 2);

                if (!$better(
                    $values[$pos],
                    $ids[$pos],
                    $values[$parent],
                    $ids[$parent],
                    $isMin
                )) {
                    break;
                }

                [$values[$pos], $values[$parent]] = [$values[$parent], $values[$pos]];
                [$ids[$pos], $ids[$parent]] = [$ids[$parent], $ids[$pos]];
                $pos = $parent;
            }
        };

        $pop = function (&$values, &$ids, $isMin) use ($better) {
            $rootValue = $values[0];
            $rootId = $ids[0];

            $lastValue = array_pop($values);
            $lastId = array_pop($ids);

            if (count($values) > 0) {
                $values[0] = $lastValue;
                $ids[0] = $lastId;

                $size = count($values);
                $pos = 0;

                while (true) {
                    $left = $pos * 2 + 1;
                    $right = $left + 1;
                    $best = $pos;

                    if (
                        $left < $size &&
                        $better(
                            $values[$left],
                            $ids[$left],
                            $values[$best],
                            $ids[$best],
                            $isMin
                        )
                    ) {
                        $best = $left;
                    }

                    if (
                        $right < $size &&
                        $better(
                            $values[$right],
                            $ids[$right],
                            $values[$best],
                            $ids[$best],
                            $isMin
                        )
                    ) {
                        $best = $right;
                    }

                    if ($best === $pos) {
                        break;
                    }

                    [$values[$pos], $values[$best]] = [$values[$best], $values[$pos]];
                    [$ids[$pos], $ids[$best]] = [$ids[$best], $ids[$pos]];
                    $pos = $best;
