                $pop($lowerValues, $lowerIds, false);
                unset($delayed[$id]);
            }
        };

        $pruneUpper = function () use (&$upperValues, &$upperIds, &$delayed, $pop) {
            while (count($upperValues) > 0) {
                $id = $upperIds[0];

                if (!isset($delayed[$id])) {
                    break;
                }

                $pop($upperValues, $upperIds, true);
                unset($delayed[$id]);
            }
        };

        $rebalance = function () use (
            &$lowerValues,
            &$lowerIds,
            &$upperValues,
            &$upperIds,
            &$lowerCount,
            &$upperCount,
            $pruneLower,
            $pruneUpper,
            $pop,
            $push
        ) {
            $pruneLower();
            $pruneUpper();

            while ($lowerCount > $upperCount + 1) {
                [$value, $id] = $pop($lowerValues, $lowerIds, false);
                $push($upperValues, $upperIds, $value, $id, true);
                $lowerCount--;
                $upperCount++;
