            while ($lowerCount < $upperCount) {
                [$value, $id] = $pop($upperValues, $upperIds, true);
                $push($lowerValues, $lowerIds, $value, $id, false);
                $upperCount--;
                $lowerCount++;
            }
        };

        $insert = function ($value, $id) use (
            &$lowerValues,
            &$lowerIds,
            &$upperValues,
            &$upperIds,
            &$lowerCount,
            &$upperCount,
            &$side,
            $push,
            $pruneLower,
            $pruneUpper,
            $rebalance
        ) {
            $pruneLower();
            $pruneUpper();

            if ($lowerCount === 0 || $value <= $lowerValues[0]) {
                $push($lowerValues, $lowerIds, $value, $id, false);
                $side[$id] = 0;
                $lowerCount++;
            } else {
                $push($upperValues, $upperIds, $value, $id, true);
                $side[$id] = 1;
                $upperCount++;
            }

            $rebalance();
        };

        $n = count($nums);
        $result = [];

        for ($i = 0; $i < $n; $i++) {
            $insert($nums[$i], $i);

            if ($i >= $k) {
