    function regionsBySlashes($grid) {
        $n = count($grid);
        $total = $n * $n * 4;
        $parent = [];

        for ($i = 0; $i < $total; $i++) {
            $parent[$i] = $i;
        }

        $find = function ($x) use (&$parent) {
            $root = $x;

            while ($parent[$root] !== $root) {
                $root = $parent[$root];
            }

            while ($parent[$x] !== $x) {
                $next = $parent[$x];
                $parent[$x] = $root;
                $x = $next;
            }

            return $root;
        };

        $union = function ($a, $b) use (&$parent, &$find) {
            $rootA = $find($a);
            $rootB = $find($b);

            if ($rootA !== $rootB) {
                $parent[$rootA] = $rootB;
            }
        };

        for ($r = 0; $r < $n; $r++) {
            for ($c = 0; $c < $n; $c++) {
                $base = ($r * $n + $c) * 4;
                $cell = $grid[$r][$c];

                if ($cell === '/') {
                    $union($base, $base + 3);
                    $union($base + 1, $base + 2);
                } elseif ($cell === '\\') {
                    $union($base, $base + 1);
                    $union($base + 2, $base + 3);
                } else {
                    $union($base, $base + 1);
                    $union($base + 1, $base + 2);
                    $union($base + 2, $base + 3);
                }

                if ($r + 1 < $n) {
                    $below = (($r + 1) * $n + $c) * 4;
                    $union($base + 2, $below);
                }

                if ($c + 1 < $n) {
                    $right = ($r * $n + $c + 1) * 4;
                    $union($base + 1, $right + 3);
                }
            }
        }

        $regions = 0;

        for ($i = 0; $i < $total; $i++) {
            if ($find($i) === $i) {
                $regions++;
            }
        }

        return $regions;
    }
}
