class Solution {

    /**
     * @param Integer[] $arr
     * @return Integer[]
     */
    function sortByBits($arr) {
        $popcount = function ($x) {
            $count = 0;
            while ($x > 0) {
                $count += ($x & 1);
                $x >>= 1;
            }
            return $count;
        };

        usort($arr, function ($a, $b) use ($popcount) {
            $bitsA = $popcount($a);
            $bitsB = $popcount($b);

            if ($bitsA !== $bitsB) {
                return $bitsA <=> $bitsB;
            }

            return $a <=> $b;
        });

        return $arr;
    }
}
