class Solution {

    /**
     * @param Integer $n
     * @param Integer $firstPlayer
     * @param Integer $secondPlayer
     * @return Integer[]
     */
    function earliestAndLatest($n, $firstPlayer, $secondPlayer) {
        $memo = [];
        $dfs = null;

        $dfs = function ($size, $a, $b) use (&$dfs, &$memo) {
            $key = $size . ',' . $a . ',' . $b;

            if (isset($memo[$key])) {
                return $memo[$key];
            }

            if ($a + $b === $size + 1) {
                return $memo[$key] = [1, 1];
            }

            $states = [];
            $baseX = 0;
            $baseY = 1;

            if (($size % 2) === 1) {
                $middle = intdiv($size + 1, 2);

                if ($middle !== $a && $middle !== $b) {
                    if ($middle < $a) {
                        $baseX++;
                    }
                    if ($middle < $b) {
                        $baseY++;
                    }
                }
            }

            $states[$baseX * 32 + $baseY] = true;

            $half = intdiv($size, 2);

            for ($i = 1; $i <= $half; $i++) {
                $j = $size + 1 - $i;

                if ($i === $a || $i === $b || $j === $a || $j === $b) {
                    continue;
                }

                $nextStates = [];

                foreach ($states as $code => $_) {
                    $x = intdiv((int)$code, 32);
                    $y = (int)$code % 32;

                    $x1 = $x + (($i < $a) ? 1 : 0);
                    $y1 = $y + (($i < $b) ? 1 : 0);
                    $nextStates[$x1 * 32 + $y1] = true;

                    $x2 = $x + (($j < $a) ? 1 : 0);
                    $y2 = $y + (($j < $b) ? 1 : 0);
                    $nextStates[$x2 * 32 + $y2] = true;
                }

                $states = $nextStates;
            }

            $nextSize = intdiv($size + 1, 2);
            $earliest = PHP_INT_MAX;
            $latest = 0;

            foreach ($states as $code => $_) {
                $x = intdiv((int)$code, 32);
                $y = (int)$code % 32;

                $nextA = $x + 1;
                $nextB = $y + 1;

                $result = $dfs($nextSize, $nextA, $nextB);

                $earliest = min($earliest, $result[0] + 1);
                $latest = max($latest, $result[1] + 1);
            }

            return $memo[$key] = [$earliest, $latest];
        };

        return $dfs($n, $firstPlayer, $secondPlayer);
    }
}
