                for ($step = 0; $step < $stepLength; $step++) {
                    $r += $dr;
                    $c += $dc;

                    if ($r >= 0 && $r < $rows && $c >= 0 && $c < $cols) {
                        $result[] = [$r, $c];

                        if (count($result) === $total) {
                            return $result;
                        }
                    }
                }

                $dir = ($dir + 1) % 4;
            }

            $stepLength++;
        }

        return $result;
    }
}
