<?php

class Solution {

    /**
     * @param String[] $words
     * @param String $result
     * @return Boolean
     */
    function isSolvable($words, $result) {
        $columns = [];
        $leading = [];
        $characters = [];

        foreach ($words as $word) {
            $length = strlen($word);

            if ($length > 1) {
                $leading[$word[0]] = true;
            }

            for ($i = 0; $i < $length; $i++) {
                $characters[$word[$i]] = true;
            }

            for ($col = 0; $col < $length; $col++) {
                if (!isset($columns[$col])) {
                    $columns[$col] = [];
                }
                $columns[$col][] = $word[$length - 1 - $col];
            }
        }

        $resultLength = strlen($result);
        if ($resultLength > 1) {
            $leading[$result[0]] = true;
        }

        for ($i = 0; $i < $resultLength; $i++) {
            $characters[$result[$i]] = true;
        }

        if (count($characters) > 10) {
            return false;
        }

        $maxColumns = max(count($columns), $resultLength);
        $mapping = [];
        $used = 0;

        $dfs = null;
        $dfs = function ($col, $carry) use (
            &$dfs,
            &$mapping,
            &$used,
            &$columns,
            &$result,
            $resultLength,
            $maxColumns,
            &$leading
        ) {
            if ($col >= $maxColumns) {
                return $carry === 0;
            }

            $addChars = isset($columns[$col]) ? $columns[$col] : [];
            $resultChar = $col < $resultLength
                ? $result[$resultLength - 1 - $col]
                : null;

            $assign = null;
            $assign = function ($index, $sum) use (
                &$assign,
                &$dfs,
                &$mapping,
                &$used,
                &$leading,
                $addChars,
                $resultChar,
                $col
            ) {
                if ($index < count($addChars)) {
                    $char = $addChars[$index];

                    if (array_key_exists($char, $mapping)) {
                        return $assign($index + 1, $sum + $mapping[$char]);
                    }

                    for ($digit = 0; $digit <= 9; $digit++) {
                        if (($used & (1 << $digit)) !== 0) {
                            continue;
                        }

                        if ($digit === 0 && isset($leading[$char])) {
                            continue;
                        }

                        $mapping[$char] = $digit;
                        $used |= (1 << $digit);

                        if ($assign($index + 1, $sum + $digit)) {
                            return true;
                        }

                        unset($mapping[$char]);
                        $used ^= (1 << $digit);
                    }

                    return false;
                }

                $requiredDigit = $sum % 10;
                $nextCarry = intdiv($sum, 10);

                if ($resultChar === null) {
                    if ($requiredDigit !== 0) {
                        return false;
                    }

                    return $dfs($col + 1, $nextCarry);
                }

                if (array_key_exists($resultChar, $mapping)) {
                    if ($mapping[$resultChar] !== $requiredDigit) {
                        return false;
                    }

                    return $dfs($col + 1, $nextCarry);
                }

                if (($used & (1 << $requiredDigit)) !== 0) {
                    return false;
                }

                if ($requiredDigit === 0 && isset($leading[$resultChar])) {
                    return false;
                }

                $mapping[$resultChar] = $requiredDigit;
                $used |= (1 << $requiredDigit);

                if ($dfs($col + 1, $nextCarry)) {
                    return true;
                }

                unset($mapping[$resultChar]);
                $used ^= (1 << $requiredDigit);

                return false;
            };

            return $assign(0, $carry);
        };

        return $dfs(0, 0);
    }
}
