    /**
     * @param String $s1
     * @param String $s2
     * @return String[]
     */
    function uncommonFromSentences($s1, $s2) {
        $count = [];

        foreach (explode(' ', $s1 . ' ' . $s2) as $word) {
            if (!isset($count[$word])) {
                $count[$word] = 0;
            }
            $count[$word]++;
        }

        $result = [];
        foreach ($count as $word => $frequency) {
            if ($frequency === 1) {
                $result[] = $word;
            }
        }

        return $result;
    }
}
