<?php
class Solution {

    /**
     * @param Integer $n
     * @param Integer[] $leftChild
     * @param Integer[] $rightChild
     * @return Boolean
     */
    function validateBinaryTreeNodes($n, $leftChild, $rightChild) {
        $indegree = array_fill(0, $n, 0);

        for ($i = 0; $i < $n; $i++) {
            foreach ([$leftChild[$i], $rightChild[$i]] as $child) {
                if ($child !== -1) {
                    $indegree[$child]++;
                    if ($indegree[$child] > 1) {
                        return false;
                    }
                }
            }
        }

        $root = -1;
        for ($i = 0; $i < $n; $i++) {
            if ($indegree[$i] === 0) {
                if ($root !== -1) {
                    return false;
                }
                $root = $i;
            }
        }

        if ($root === -1) {
            return false;
        }

        $visited = array_fill(0, $n, false);
        $queue = [$root];
        $visited[$root] = true;
        $head = 0;
        $count = 0;

        while ($head < count($queue)) {
            $node = $queue[$head++];
            $count++;

            foreach ([$leftChild[$node], $rightChild[$node]] as $child) {
                if ($child !== -1 && !$visited[$child]) {
                    $visited[$child] = true;
                    $queue[] = $child;
                }
            }
        }

        return $count === $n;
    }
}
