    /**
     * @param String $beginWord
     * @param String $endWord
     * @param String[] $wordList
     * @return Integer
     */
    function ladderLength($beginWord, $endWord, $wordList) {
        $dictionary = array_flip($wordList);

        if (!isset($dictionary[$endWord])) {
            return 0;
        }

        $queue = [$beginWord];
        $distance = [$beginWord => 1];
        $head = 0;

        unset($dictionary[$beginWord]);

        $length = strlen($beginWord);

        while ($head < count($queue)) {
            $word = $queue[$head++];
            $currentDistance = $distance[$word];

            for ($i = 0; $i < $length; $i++) {
                $original = $word[$i];

                for ($code = 97; $code <= 122; $code++) {
                    $replacement = chr($code);

                    if ($replacement === $original) {
                        continue;
                    }

                    $nextWord = substr_replace($word, $replacement, $i, 1);

                    if ($nextWord === $endWord && isset($dictionary[$nextWord])) {
                        return $currentDistance + 1;
                    }

                    if (isset($dictionary[$nextWord])) {
                        unset($dictionary[$nextWord]);
                        $queue[] = $nextWord;
                        $distance[$nextWord] = $currentDistance + 1;
                    }
                }
            }
        }

        return 0;
    }
}
